import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

// Single fused elementwise Tanh kernel (fast-math optimized).
// Optimization: compute tanh with CUDA fast-math intrinsics instead of
// the branchy, high-latency libdevice tanhf slow path:
//   tanh(x) = sign(x) * (1 - e) / (1 + e),  e = __expf(-2*|x|)
// e in (0, 1] so there is no overflow/underflow instability, and the
// __expf / __fdividef pair cuts instruction count and register pressure
// so this memory-bound kernel sustains DRAM bandwidth with fewer stalls.
// Each thread processes 4 contiguous elements via float4 vectorized
// loads/stores; the last (up to 3) tail elements are handled by the
// first threads, so exactly one kernel launch is needed.
__device__ __forceinline__ float fast_tanhf(float x) {
    const float e = __expf(-2.0f * fabsf(x));  // in (0, 1], never overflows
    const float t = __fdividef(1.0f - e, 1.0f + e);
    return copysignf(t, x);
}
__global__ void tanh_kernel(const float* __restrict__ in,
                            float* __restrict__ out,
                            const long n) {
    const long n4 = n >> 2;  // number of full float4 groups
    const long tid = (long)blockIdx.x * blockDim.x + threadIdx.x;
    const long stride = (long)gridDim.x * blockDim.x;
    const float4* in4  = reinterpret_cast<const float4*>(in);
    float4*       out4 = reinterpret_cast<float4*>(out);
    for (long idx = tid; idx < n4; idx += stride) {
        float4 v = in4[idx];
        v.x = fast_tanhf(v.x);
        v.y = fast_tanhf(v.y);
        v.z = fast_tanhf(v.z);
        v.w = fast_tanhf(v.w);
        out4[idx] = v;
    }
    // Handle the scalar tail (n % 4 elements) with the first threads.
    const long tail_start = n4 << 2;
    if (tid < n - tail_start) {
        const long i = tail_start + tid;
        out[i] = fast_tanhf(in[i]);
    }
}

torch::Tensor tanh_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");

    auto out = torch::empty_like(x);
    const long n = x.numel();
    if (n == 0) return out;

    // Occupancy / scheduling tuning (elementwise opt #7): use smaller 128-thread
    // blocks. Profiler shows achieved occupancy (81.5%) well below theoretical
    // (100%) from warp scheduling/load imbalance. Finer-grained blocks balance
    // better across SMs, and with the fixed grid cap each thread now covers ~2
    // float4 groups via the grid-stride loop, putting more independent loads in
    // flight to push DRAM utilization (93.8%) closer to peak. Semantics unchanged.
    const int threads = 128;
    const long n4 = (n + 3) >> 2;
    long blocks = (n4 + threads - 1) / threads;
    // Cap the grid; grid-stride loop covers the rest.
    const long max_blocks = 65535L * 8L;
    if (blocks > max_blocks) blocks = max_blocks;

    tanh_kernel<<<(int)blocks, threads>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        n);

    return out;
}
"""

cpp_src = "torch::Tensor tanh_forward(torch::Tensor x);"

_tanh_mod = load_inline(
    name="tanh_cuda_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_mod.tanh_forward(x)

